-- All fixtures and assertions are transactional and rolled back.
begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end $$;
insert into auth.users(id,email) values('00000000-0000-4000-8000-00000000ca01','journey-owner@example.invalid'),('00000000-0000-4000-8000-00000000cb01','journey-other@example.invalid'),('00000000-0000-4000-8000-00000000cc01','journey-viewer@example.invalid');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000ca01","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
insert into public.atraction_tenants(id,name,owner_id,capture_enabled,capture_slug) values('00000000-0000-4000-8000-00000000ca02','Journey A','00000000-0000-4000-8000-00000000ca01',true,'journey-capture-test');
insert into public.atraction_contacts(id,tenant_id,owner_id,name,phone) values('00000000-0000-4000-8000-00000000ca03','00000000-0000-4000-8000-00000000ca02','00000000-0000-4000-8000-00000000ca01','Journey client','+5521999999991');
insert into public.atraction_deals(id,tenant_id,owner_id,contact_id,title,value,stage) values('00000000-0000-4000-8000-00000000ca04','00000000-0000-4000-8000-00000000ca02','00000000-0000-4000-8000-00000000ca01','00000000-0000-4000-8000-00000000ca03','Journey sale',100,1);
select public.atraction_create_contract('{"id":"00000000-0000-4000-8000-00000000ca05","tenant_id":"00000000-0000-4000-8000-00000000ca02","contact_id":"00000000-0000-4000-8000-00000000ca03","deal_id":"00000000-0000-4000-8000-00000000ca04","title":"Journey installments","mode":"installments","amount_cents":10000,"periods":3,"start_date":"2028-01-31","first_due_date":"2028-01-31"}');
select pg_temp.assert_true((select sum(amount_cents)=10000 and count(*)=3 from public.atraction_finance),'installments preserve cents');
select pg_temp.assert_true((select due_date='2028-02-29' from public.atraction_finance where installment=2),'leap month date');
select pg_temp.assert_true((select stage=4 from public.atraction_deals),'sale marked won');
select pg_temp.assert_true((select lifecycle='customer' from public.atraction_contacts),'client promoted');
select pg_temp.assert_true((select count(*)=1 from public.atraction_activities where purpose='onboarding'),'onboarding created once');
select public.atraction_create_contract('{"id":"00000000-0000-4000-8000-00000000ca05","tenant_id":"00000000-0000-4000-8000-00000000ca02"}');
select pg_temp.assert_true((select count(*)=3 from public.atraction_finance),'idempotent retry');
do $$begin begin perform public.atraction_create_contract('{"id":"00000000-0000-4000-8000-00000000ca06","tenant_id":"00000000-0000-4000-8000-00000000ca02","contact_id":"00000000-0000-4000-8000-00000000ca03","deal_id":"00000000-0000-4000-8000-00000000ca04","title":"Duplicate sale","mode":"once","amount_cents":10000,"periods":1,"start_date":"2028-01-31","first_due_date":"2028-01-31"}');raise exception 'FAIL: duplicate sale contract';exception when unique_violation then null;end;end $$;
select pg_temp.assert_true((select count(*)=1 from public.atraction_contracts),'duplicate transaction rolled back');
select public.atraction_create_contract('{"id":"00000000-0000-4000-8000-00000000ca07","tenant_id":"00000000-0000-4000-8000-00000000ca02","contact_id":"00000000-0000-4000-8000-00000000ca03","title":"Monthly plan","mode":"monthly","amount_cents":10000,"periods":3,"start_date":"2028-01-31","first_due_date":"2028-01-31"}');
select public.atraction_record_payment(id,amount_cents,current_date,null,gen_random_uuid()) from public.atraction_finance where contract_id='00000000-0000-4000-8000-00000000ca07' and installment=1;
select public.atraction_contract_action('00000000-0000-4000-8000-00000000ca07','adjust',12000,current_date);
select pg_temp.assert_true((select amount_cents=10000 from public.atraction_finance where contract_id='00000000-0000-4000-8000-00000000ca07' and installment=1),'paid installment unchanged');
select pg_temp.assert_true((select count(*)=2 from public.atraction_finance where contract_id='00000000-0000-4000-8000-00000000ca07' and amount_cents=12000),'open monthly installments adjusted');
select public.atraction_create_contract('{"id":"00000000-0000-4000-8000-00000000ca08","tenant_id":"00000000-0000-4000-8000-00000000ca02","contact_id":"00000000-0000-4000-8000-00000000ca03","renews_id":"00000000-0000-4000-8000-00000000ca07","title":"Renewed plan","mode":"monthly","amount_cents":12000,"periods":3,"start_date":"2028-04-30","first_due_date":"2028-04-30"}');
select pg_temp.assert_true((select count(*)=9 from public.atraction_finance),'renewal creates distinct next period');
select public.atraction_contract_action('00000000-0000-4000-8000-00000000ca07','cancel',0,current_date);
select pg_temp.assert_true((select count(*)=2 from public.atraction_finance where contract_id='00000000-0000-4000-8000-00000000ca07' and deleted_at is not null),'cancel archives unpaid future only');
select pg_temp.assert_true((select count(*)=1 from public.atraction_finance where contract_id='00000000-0000-4000-8000-00000000ca07' and settled_date is not null and deleted_at is null),'cancel preserves receipts');
do $$begin begin update public.atraction_finance set contract_id=null,installment=null where contract_id='00000000-0000-4000-8000-00000000ca08';raise exception 'FAIL: detach installment';exception when raise_exception then if sqlerrm='FAIL: detach installment' then raise;end if;end;end $$;
insert into public.atraction_documents(id,tenant_id,owner_id,contact_id,name,path,mime_type,size) values('00000000-0000-4000-8000-00000000ca09','00000000-0000-4000-8000-00000000ca02','00000000-0000-4000-8000-00000000ca01','00000000-0000-4000-8000-00000000ca03','Test.pdf','00000000-0000-4000-8000-00000000ca02/00000000-0000-4000-8000-00000000ca09','application/pdf',100);
insert into storage.objects(bucket_id,name) values('atraction-documents','00000000-0000-4000-8000-00000000ca02/00000000-0000-4000-8000-00000000ca09');
select pg_temp.assert_true((select count(*)=1 from storage.objects where bucket_id='atraction-documents'),'owner can read own file');
-- Other account cannot read or operate on these contracts or document objects.
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000cb01","role":"authenticated","aal":"aal2"}',true);
insert into public.atraction_tenants(id,name,owner_id) values('00000000-0000-4000-8000-00000000cb02','Journey B','00000000-0000-4000-8000-00000000cb01');
select pg_temp.assert_true((select count(*)=0 from public.atraction_contracts),'cross tenant contracts hidden');
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='atraction-documents'),'cross tenant files hidden');
do $$begin begin perform public.atraction_contract_action('00000000-0000-4000-8000-00000000ca08','cancel',0,current_date);raise exception 'FAIL: cross tenant action';exception when raise_exception then if sqlerrm='FAIL: cross tenant action' then raise;end if;end;end $$;
reset role;
insert into public.atraction_members(tenant_id,user_id,role) values('00000000-0000-4000-8000-00000000ca02','00000000-0000-4000-8000-00000000cc01','viewer');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000cc01","role":"authenticated","aal":"aal1"}',true);
select pg_temp.assert_true((select count(*)=0 from public.atraction_contracts),'viewer contracts hidden');
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='atraction-documents'),'viewer files hidden');
select pg_temp.assert_true((select count(*)=0 from public.atraction_events where entity in ('contracts','documents')),'viewer sensitive audit hidden');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000ca01","role":"authenticated","aal":"aal1"}',true);
select pg_temp.assert_true((select count(*)=0 from public.atraction_contracts),'MFA required');
-- Anonymous attributed capture and first touch retention.
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select public.atraction_capture_attributed('journey-capture-test','Campaign lead','+5521999999992',true,'{"utm_source":"Instagram","utm_campaign":"Spring","utm_medium":"social","ref":"Client A"}');
select public.atraction_capture_attributed('journey-capture-test','Campaign lead','+5521999999992',true,'{"utm_source":"Other","utm_campaign":"Overwrite"}');
reset role;
select pg_temp.assert_true((select source='Instagram' and campaign='Spring' and referred_by='Client A' from public.atraction_contacts where phone='+5521999999992'),'first touch attribution preserved');
rollback;
